dataSchema.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:orbyss:forms:synthetic-product:1",
  "title": "Synthetic configurable product",
  "type": "object",
  "properties": {
    "detail": {
      "type": "string",
      "title": "Custom detail",
      "x-i18n": "fields.detail",
      "minLength": 1
    },
    "editable": {
      "type": "boolean",
      "title": "Allow editing",
      "x-i18n": "fields.editable"
    },
    "kind": {
      "type": "string",
      "title": "Product type",
      "x-i18n": "fields.kind",
      "oneOf": [
        {
          "const": "custom",
          "title": "Custom",
          "x-i18n": "choices.custom"
        },
        {
          "const": "standard",
          "title": "Standard",
          "x-i18n": "choices.standard"
        }
      ]
    },
    "name": {
      "type": "string",
      "title": "Name",
      "x-i18n": "fields.name",
      "description": "Use a fictitious name for this example.",
      "x-description-i18n": "fields.name.help",
      "minLength": 1
    },
    "quantity": {
      "type": "integer",
      "title": "Quantity",
      "x-i18n": "fields.quantity",
      "minimum": 1,
      "maximum": 100
    },
    "reference": {
      "type": "string",
      "readOnly": true,
      "title": "Reference",
      "x-i18n": "fields.reference"
    }
  },
  "additionalProperties": false,
  "required": [
    "kind",
    "name",
    "quantity"
  ],
  "allOf": [
    {
      "if": {
        "type": "object",
        "properties": {
          "kind": {
            "type": "string",
            "const": "custom"
          }
        },
        "required": [
          "kind"
        ]
      },
      "then": {
        "type": "object",
        "properties": {
          "detail": {}
        },
        "required": [
          "detail"
        ]
      }
    }
  ]
}

uiSchema.content:
{
  "type": "Categorization",
  "id": "journey",
  "options": {
    "variant": "orbyss-forms-wizard",
    "navigationPolicy": "visited",
    "navigationPlacement": "adaptive",
    "progressStyle": "progress",
    "validateBeforeAdvance": false,
    "saveProgress": false,
    "deepLink": false
  },
  "elements": [
    {
      "type": "Category",
      "id": "configure",
      "label": "Configure",
      "i18n": "steps.configure",
      "elements": [
        {
          "type": "Control",
          "id": "name-control",
          "scope": "#/properties/name",
          "label": "Name",
          "i18n": "fields.name"
        },
        {
          "type": "Control",
          "id": "kind-control",
          "scope": "#/properties/kind",
          "label": "Product type",
          "i18n": "fields.kind"
        },
        {
          "type": "Control",
          "id": "editable-control",
          "scope": "#/properties/editable",
          "label": "Allow editing",
          "i18n": "fields.editable"
        },
        {
          "type": "VerticalLayout",
          "id": "editable-details",
          "elements": [
            {
              "type": "VerticalLayout",
              "rule": {
                "effect": "SHOW",
                "condition": {
                  "scope": "#",
                  "schema": {
                    "type": "object",
                    "properties": {
                      "kind": {
                        "type": "string",
                        "const": "custom"
                      }
                    },
                    "required": [
                      "kind"
                    ]
                  },
                  "failWhenUndefined": true
                }
              },
              "elements": [
                {
                  "type": "Control",
                  "id": "detail-control",
                  "scope": "#/properties/detail",
                  "label": "Custom detail",
                  "i18n": "fields.detail",
                  "rule": {
                    "effect": "ENABLE",
                    "condition": {
                      "scope": "#",
                      "failWhenUndefined": true,
                      "schema": {
                        "allOf": [
                          {
                            "type": "object",
                            "properties": {
                              "editable": {
                                "type": "boolean",
                                "const": true
                              }
                            },
                            "required": [
                              "editable"
                            ]
                          },
                          {
                            "type": "object",
                            "properties": {
                              "kind": {
                                "type": "string",
                                "const": "custom"
                              }
                            },
                            "required": [
                              "kind"
                            ]
                          }
                        ]
                      }
                    }
                  }
                }
              ]
            }
          ],
          "rule": {
            "effect": "ENABLE",
            "condition": {
              "scope": "#",
              "failWhenUndefined": true,
              "schema": {
                "allOf": [
                  {
                    "type": "object",
                    "properties": {
                      "editable": {
                        "type": "boolean",
                        "const": true
                      }
                    },
                    "required": [
                      "editable"
                    ]
                  }
                ]
              }
            }
          }
        }
      ]
    },
    {
      "type": "Category",
      "id": "review",
      "label": "Review",
      "i18n": "steps.review",
      "elements": [
        {
          "type": "Control",
          "id": "quantity-control",
          "scope": "#/properties/quantity",
          "label": "Quantity",
          "i18n": "fields.quantity"
        },
        {
          "type": "Control",
          "id": "reference-control",
          "scope": "#/properties/reference",
          "label": "Reference",
          "i18n": "fields.reference",
          "options": {
            "readonly": true
          }
        },
        {
          "type": "Orbyss.Forms.ActionBar",
          "id": "actions",
          "options": {
            "actions": [
              "calculate"
            ]
          }
        }
      ]
    }
  ]
}

